"""AQS-OPS-003 critical spares list (X-OPS-03, A-M-185). From the plant BOM families: building blocks (AQS-INV-004) and motor
families (AQS-INV-005) by the spares rule (fraction of installed, with a minimum); consumable process inserts by unit from the unit
designs (one charge or set of: BMED membranes, RO membranes and EDI stack, 13X sorbent bed, catalyst charges, H2 purifier beds,
compressor diaphragms, PSV bores). Spares are made in-house from the same production plans. Run: python3 docs-authority/_spares.py"""
import csv, json, math, os, sys
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R); sys.path.insert(0, R)
from flow_graph.param import drivers as DR
d = DR.load(); rule = DR.val(d, 'spares_rule'); I = 'docs-authority/inventory/'
rows = []
for r in csv.DictReader(open(I + 'OTHER_FAMILIES.csv')):
    f, mn = rule.get(r['category'], [0.05, 1]); q = int(r['qty']); s = max(mn, math.ceil(q*f)) if f or mn else 0
    if s: rows.append(('building block', r['family'], f"{r['category']}: {r['item']} ({r['sizes'][:60]})", q, s, f"{f*100:.0f} % min {mn}"))
f, mn = rule['motor']
for r in csv.DictReader(open(I + 'MOTOR_FAMILIES.csv')):
    q = int(r['count']); rows.append(('motor', r['family'], f"{r['motor_type']} {r['size']} {r['voltage']}", q, max(mn, math.ceil(q*f)), f"{f*100:.0f} % min {mn}"))
g = json.load(open('flow_graph/plant_flow_graph.json')); N = {n['unit_id']: n for n in g['nodes']}
dz = lambda u: (N[u]['params'].get('design') or {})
ins = [('BMED_ACID', 'one stack of bipolar, anion and cation membranes (AQS-DUTY-068 spare stack is installed; this is the membrane set to rebuild it)', 1),
       ('BMED_UPW_POLISH', 'RO flat-sheet set and one EDI stack (AQS-DUTY-070)', 1),
       ('CRYO_ASU', f"13X sorbent charge, {dz('CRYO_ASU').get('sorbent_kg_per_bed', 0):.0f} kg (AQS-DUTY-069)", 1),
       ('CRYO_H2', 'compressor diaphragm set, one per stage (AQS-DUTY-067)', 1),
       ('H2_PURIFIER', 'deoxo, guard and TSA bed charges (AQS-DUTY-066)', 1),
       ('MEOH_SYNTH', 'Cu/ZnO/Al2O3 catalyst charge (AQS-DUTY-062)', 1), ('ALD', 'Cu/SiO2 catalyst charge', 1), ('FORM', 'FeMo catalyst charge', 1), ('MEAM', 'silica-alumina catalyst charge', 1),
       ('HNO3', 'Pt-Rh gauze pack (AQS-DUTY-062 section 7)', 1), ('ACEX', 'OH-form anion resin charge (AQS-DUTY-062)', 1),
       ('ZNBR2', 'electrode and separator set for one stack (AQS-TST-002 stack design)', 1),
       ('RELIEF', 'PSV, 6 mm bore DN15 body, one per set-pressure class (AQS-SAF-004)', 3)]
for u, t, s in ins: rows.append(('process insert', u, t, 1, s, 'one charge or set'))
md = ['# Critical spares list', '', 'Document number: AQS-OPS-003', 'Revision: A', 'Date: 2026-10-16', 'Authority: AQS-PLAN-007 X-OPS-03. Generated by `docs-authority/_spares.py` from the plant BOM families. Study. A-M-185.', '',
      'Rule: building blocks and motors by fraction of installed with a minimum; one charge or set of each consumable process insert. Spares are made in-house on the same production plans (X-INV families).', '',
      '| Kind | Family / unit | Item | Installed | Spares | Rule |', '|---|---|---|---|---|---|']
md += [f'| {a} | {b} | {c} | {q} | {s} | {r} |' for a, b, c, q, s, r in rows]
md += ['', f"{len(rows)} lines; {sum(r[4] for r in rows if r[0] == 'motor')} spare motors, {sum(r[4] for r in rows if r[0] == 'building block')} building-block spares, {sum(1 for r in rows if r[0] == 'process insert')} process insert sets. Intervals and failure rates are X-OPS-02."]
open('docs-authority/SPARES.md', 'w').write('\n'.join(md) + '\n'); print(len(rows))
